export default function (api: GameAPI) {
  const widgetId = 'ui-e05e8cde-6bcc-4b72-9b54-b09039edd5aa';
  let unsubscribers = [];

  function sendQuests() {
    console.log("QUEST NEED");
    api.ui.sendEvent(widgetId, 'hud.quests.data', api.dialogue.listQuests());
  }

  function toggleFlashlight() {
    const playerId = api.findByTag("player")[0] ?? api.player.id;
    if (!playerId) {
      console.warn("Flashlight: игрок не найден");
      return;
    }

    const flashId = api.getChildByName(playerId, "Flashlight");
    const flash = flashId ? api.find(flashId) : undefined;
    if (!flash) {
      console.warn("Flashlight: дочерний объект не найден");
      return;
    }

    api.setActive(flash.id, !flash.visible);
    console.log("TOGGLE", flash.active);
  }

  return {
    onStart() {
      unsubscribers = [
        api.events.on('hud.quests.request', sendQuests),
        api.events.on('quest.updated', sendQuests),
        api.events.on('save.loaded', sendQuests),
        api.events.on('hud.flashlight', toggleFlashlight),
      ];
    },

    onDestroy() {
      for (const unsubscribe of unsubscribers) unsubscribe();
    },
  };
}
